82	                if let Some(literal) = expression.member().ok()?.as_any_js_literal_expression() {
83	                    if literal.as_js_string_literal_expression().is_some()
84	                        && literal.to_string() == "\"only\""
85	                    {
86	                        return Some(expression.syntax().text_trimmed_range());
87	                    }
88	                }
89	            }
90	        }
