109	    fn action(ctx: &RuleContext<Self>, _: &Self::State) -> Option<JsRuleAction> {
110	        let node = ctx.query();
111	        let callee = node.callee().ok()?;
112	
113	        let mut mutation = ctx.root().begin();
114	
115	        if let Some(function_name) = callee.get_callee_member_name() {
116	            let replaced_function;
117	            match function_name.text_trimmed() {
118	                "only" => {
119	                    if let Some(expression) = callee.as_js_static_member_expression() {
120	                        let member_name = expression.member().ok()?;
121	                        let operator_token = expression.operator_token().ok()?;
122	                        mutation.remove_element(member_name.into());
123	                        mutation.remove_element(operator_token.into());
124	                    }
125	                }
126	                "fdescribe" => {
127	                    replaced_function = make::js_reference_identifier(make::ident("describe"));
128	                    mutation.replace_element(function_name.into(), replaced_function.into());
129	                }
130	                "fit" => {
131	                    replaced_function = make::js_reference_identifier(make::ident("it"));
132	                    mutation.replace_element(function_name.into(), replaced_function.into());
133	                }
134	                _ => {}
135	            };
136	        } else if let Some(expression) = callee.as_js_computed_member_expression() {
137	            let l_brack = expression.l_brack_token().ok()?;
138	            let r_brack = expression.r_brack_token().ok()?;
139	            let member = expression.member().ok()?;
140	            let expression = member.as_any_js_literal_expression()?;
141	            mutation.remove_element(NodeOrToken::Token(l_brack));
142	            mutation.remove_element(NodeOrToken::Node(expression.syntax().clone()));
143	            mutation.remove_element(NodeOrToken::Token(r_brack));
144	        };
145	
146	        Some(JsRuleAction {
147	            category: biome_analyze::ActionCategory::QuickFix,
148	            applicability: Applicability::MaybeIncorrect,
149	            message: markup! { "Remove focus from test." }.to_owned(),
150	            mutation,
151	        })
152	    }
