11	declare_rule! {
12	    /// Disallow using a callback in asynchronous tests and hooks.
13	    ///
14	    /// This rule checks the function parameter of hooks & tests for use of the done argument, suggesting you return a promise instead.
15	    ///
16	    /// ## Examples
17	    ///
18	    /// ### Invalid
19	    ///
20	    /// ```js,expect_diagnostic
21	    /// beforeEach(done => {
22	    ///     // ...
23	    /// });
24	    /// ```
25	    ///
26	    /// ```js,expect_diagnostic
27	    /// test('myFunction()', done => {
28	    ///     // ...
29	    /// });
30	    /// ```
31	    ///
32	    /// ### Valid
33	    ///
34	    /// ```js
35	    /// beforeEach(async () => {
36	    ///     // ...
37	    /// });
38	    /// ```
39	    ///
40	    /// ```js
41	    /// test('myFunction()', () => {
42	    ///     expect(myFunction()).toBeTruthy();
43	    /// });
44	    /// ```
45	    ///
46	    pub NoDoneCallback {
47	        version: "next",
48	        name: "noDoneCallback",
49	        recommended: true,
50	        source: RuleSource::EslintJest("no-done-callback"),
51	        source_kind: RuleSourceKind::SameLogic,
52	    }
53	}
