55	impl Rule for NoDoneCallback {
56	    type Query = Ast<JsCallExpression>;
57	    type State = TextRange;
58	    type Signals = Option<Self::State>;
59	    type Options = ();
60	
61	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
62	        let node = ctx.query();
63	
64	        let callee = node.callee().ok()?;
65	
66	        let is_test_each = callee
67	            .get_callee_member_name()
68	            .map_or(false, |m| m.text_trimmed() == "each");
69	
70	        if is_test_each && !JsTemplateExpression::can_cast(callee.syntax().kind()) {
71	            return None;
72	        }
73	
74	        let arguments = &node.arguments().ok()?;
75	        let callee_name = callee.get_callee_object_name()?;
76	
77	        let argument_index = match callee_name.text_trimmed() {
78	            "after" | "afterAll" | "afterEach" | "before" | "beforeAll" | "beforeEach" => 0,
79	            "it" | "test" => 1, // for test.each() and test() we want the second argument
80	            _ => return None,
81	        };
82	        let argument = arguments
83	            .get_arguments_by_index([argument_index])
84	            .first()?
85	            .clone();
86	
87	        let callback = argument?;
88	        let callback = callback.as_any_js_expression()?;
89	
90	        match callback {
91	            AnyJsExpression::JsArrowFunctionExpression(arrow_function) => {
92	                let parameter = arrow_function.parameters().ok()?;
93	                match parameter {
94	                    AnyJsArrowFunctionParameters::AnyJsBinding(binding) => {
95	                        let param = binding.as_js_identifier_binding()?;
96	                        let text_range = param.name_token().ok()?;
97	                        let text_range = text_range.text_trimmed_range();
98	                        return Some(text_range);
99	                    }
100	                    AnyJsArrowFunctionParameters::JsParameters(js_parameters) => {
101	                        return analyze_js_parameters(&js_parameters, is_test_each)
102	                    }
103	                }
104	            }
105	            AnyJsExpression::JsFunctionExpression(js_function) => {
106	                let js_parameters = js_function.parameters().ok()?;
107	                return analyze_js_parameters(&js_parameters, is_test_each);
108	            }
109	            _ => {}
110	        }
111	
112	        None
