34	    type State = ();
35	    type Signals = Option<Self::State>;
36	    type Options = ();
37	
38	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
39	        let call_expression = ctx.query();
40	        let model = ctx.model();
41	        let callee = call_expression.callee().ok()?;
42	        let member_expression = AnyJsMemberExpression::cast_ref(callee.syntax())?;
43	        let object = member_expression.object().ok()?;
44	        let (reference, name) = global_identifier(&object)?;
45	        if name.text() != "console" {
46	            return None;
47	        }
